mapper.select:
select cat_parent_id
from ${database.prefix.goods}hou_goods_cat
where cat_id = #{param.productClassId,jdbcType=INTEGER}

select count(1)
from ${database.prefix.goods}hou_goods_cat
where cat_parent_id = #{param,jdbcType=INTEGER}

select
from ${database.prefix.goods}hou_goods_cat where cat_show_status = 1 and (is_integral_goods != 1 or is_integral_goods is null)
and cat_parent_id = #{catParentId,jdbcType=INTEGER}
order by cat_displayorder asc

select cat_parent_id from ${database.prefix.goods}hou_goods_cat where cat_show_status = 1 and (is_integral_goods != 1 or is_integral_goods is null)

    and cat_id  in


            #{catid}

select cat_id, cat_name, cat_parent_id, cat_pic from ${database.prefix.goods}hou_goods_cat where cat_show_status = 1
and (is_integral_goods != 1 or is_integral_goods is null)
and is_integral_goods = 1
and cat_parent_id = #{param.catId,jdbcType=INTEGER}
and (select count(1) from ${database.prefix.goods}hou_goods_base gb LEFT JOIN ${database.prefix.goods}hou_goods_stock gs on gb.goods_id = gs.goods_id left join ${database.prefix.goods}hou_goods_common gc on (gb.common_id = gc.common_id) where gc.common_state=1 and gc.common_verify = 1 and gb.goods_is_shelves=1 and gs.goods_stock >0 and gb.cat_id in
#{catId}
)>0
order by cat_displayorder asc

select gc.cat_id, gc.cat_name, gc.cat_pic, gc.type_id, gc.cat_commission, gc.cat_is_virtual, gc.cat_displayorder, gc.cat_show_status, gc.cat_parent_id, gc.cat_level, gt.type_name, gc.is_integral_goods, gc.refund_ratio, gc.refund_proportion, gc.group_id FROM ${database.prefix.goods}hou_goods_cat gc LEFT JOIN ${database.prefix.goods}hou_goods_type gt ON gc.type_id = gt.type_id where gc.is_integral_goods = 0
and gc.cat_show_status = #{param.catShowStatus,jdbcType=BIT}
and gc.is_integral_goods = #{param.isIntegralGoods,jdbcType=BIT}
order by gc.cat_displayorder,gc.cat_id asc

select count( 1 ) FROM ${database.prefix.goods}hou_goods_cat gc LEFT JOIN ${database.prefix.goods}hou_goods_type gt ON gc.type_id = gt.type_id where gc.is_integral_goods = 0
and gc.cat_parent_id = #{param.catParentId}
and gc.cat_show_status = #{param.catShowStatus,jdbcType=BIT}
and gc.is_integral_goods = #{param.isIntegralGoods,jdbcType=BIT}
order by gc.cat_displayorder asc

select gc.cat_id, gc.cat_name, gc.cat_pic, gc.type_id, gc.cat_commission, gc.cat_is_virtual, gc.cat_displayorder, gc.cat_show_status, gc.cat_parent_id, gc.cat_level, gt.type_name, gc.is_integral_goods FROM ${database.prefix.goods}hou_goods_cat gc LEFT JOIN ${database.prefix.goods}hou_goods_type gt ON gc.type_id = gt.type_id where is_integral_goods != 1
and gc.cat_show_status = #{catShowStatus,jdbcType=BIT}
order by gc.cat_displayorder asc

select count( 1 ) FROM ${database.prefix.goods}hou_goods_cat gc LEFT JOIN ${database.prefix.goods}hou_goods_type gt ON gc.type_id = gt.type_id where gc.cat_parent_id = 0 and is_integral_goods != 1
and gc.cat_show_status = #{catShowStatus,jdbcType=BIT}
order by gc.cat_displayorder asc

select id, supplier_shop_id, supplier_shop_name, supplier_user_id, supplier_user_name, dealer_shop_id, dealer_shop_name, dealer_user_id, dealer_user_name, dealer_user_phone, dealer_status, dealer_remark, dealer_level_id, dealer_level_name, dealer_discount, create_time from ${database.prefix.userms}hou_base_dealer_apply_info where dealer_shop_id = #{dealerShopId}
and supplier_shop_id in
#{shopId}
and dealer_status = 2

select
from ${database.prefix.goods}hou_goods_cat where 1=1
and cat_parent_id = #{catParentId,jdbcType=INTEGER}

