select cat_id, cat_name, cat_parent_id, cat_pic from ${database.prefix.goods}hou_goods_cat where cat_show_status = 1
and cat_parent_id = #{catId}
order by cat_displayorder asc

SELECT count(gc.common_id) FROM ${database.prefix.goods}hou_goods_common gc
WHERE gc.common_state = 1 and gc.common_verify = 1 and gc.shop_status = 3 and gc.is_delete = 0 AND gc.cat_id in

    #{catId}

