select
from ${database.prefix.goods}hou_goods_cat where 1=1
and cat_id = #{catId,jdbcType=INTEGER}

select batch_id,start,reason from ${database.prefix.supplier}hou_supplier_shop_class_bind_tmp where supplier_shop_id = #{param.shopId}
and cat_name like concat('%',#{param.catName},'%')
group by batch_id order by creat_time desc

select gc.cat_id, gc.cat_name, gc.cat_pic, gc.type_id, gc.cat_commission, gc.cat_is_virtual, gc.refund_ratio, gc.refund_proportion, gc.cat_displayorder, gc.cat_show_status, gc.cat_parent_id, gc.cat_level, gt.type_name, gc.is_integral_goods FROM ${database.prefix.goods}hou_goods_cat gc LEFT JOIN ${database.prefix.goods}hou_goods_type gt ON gc.type_id = gt.type_id
and gc.cat_show_status = #{catShowStatus,jdbcType=BIT}
order by gc.cat_displayorder,gc.cat_id asc

select count( 1 ) FROM ${database.prefix.goods}hou_goods_cat gc LEFT JOIN ${database.prefix.goods}hou_goods_type gt ON gc.type_id = gt.type_id where gc.cat_parent_id = 0
and gc.cat_show_status = #{catShowStatus,jdbcType=BIT}
order by gc.cat_displayorder asc

select cat_id, cat_name, cat_displayorder from ${database.prefix.goods}hou_goods_cat where cat_level = 1
and is_integral_goods = #{integralGoods}
order by cat_displayorder

select cat_id, cat_name, cat_displayorder, cat_parent_id, cat_pic, cat_level
from ${database.prefix.goods}hou_goods_cat where cat_parent_id = #{catId}
order by cat_displayorder

select cat_id,cat_name,cat_parent_id from ${database.prefix.goods}hou_goods_cat where cat_show_status = 1
and cat_parent_id = #{catParentId,jdbcType=INTEGER}
order by cat_displayorder asc
